-- Fix slips in 18 English explanations (Saagii, 29 Oct: check every explanation for mismatches with its question).
-- Each was found by reading the explanation against its passage, choices, key and (for graphs) the graph; the key and
-- choices are right, one phrase in the explanation is not. Each change applies only while the wrong phrase is still there.
-- Undo: flowersos/undo-0099.sql (kept outside the repo).

-- EXT1938: "whenever" is a subordinating conjunction, not a preposition; the explanation mislabels it ("verb and a preposition") throughout.
UPDATE public.intl_questions SET rationale = replace(rationale, 'between a verb and a preposition', 'between a verb and a subordinating conjunction') WHERE question_id = 'EXT1938' AND position('between a verb and a preposition' in rationale) > 0;
UPDATE public.intl_questions SET rationale = replace(rationale, 'a preposition ("whenever")', 'a subordinating conjunction ("whenever")') WHERE question_id = 'EXT1938' AND position('a preposition ("whenever")' in rationale) > 0;
UPDATE public.intl_questions SET rationale = replace(rationale, 'Choice A is incorrect because no punctuation is needed between the verb and the preposition', 'Choice A is incorrect because no punctuation is needed between the verb and the subordinating conjunction') WHERE question_id = 'EXT1938' AND position('Choice A is incorrect because no punctuation is needed between the verb and the preposition' in rationale) > 0;
UPDATE public.intl_questions SET rationale = replace(rationale, 'Choice B is incorrect because no punctuation is needed between the verb and the preposition', 'Choice B is incorrect because no punctuation is needed between the verb and the subordinating conjunction') WHERE question_id = 'EXT1938' AND position('Choice B is incorrect because no punctuation is needed between the verb and the preposition' in rationale) > 0;
UPDATE public.intl_questions SET rationale = replace(rationale, 'Choice C is incorrect because no punctuation is needed between the verb and the preposition', 'Choice C is incorrect because no punctuation is needed between the verb and the subordinating conjunction') WHERE question_id = 'EXT1938' AND position('Choice C is incorrect because no punctuation is needed between the verb and the preposition' in rationale) > 0;
-- EXT1262: Passage says the Gypsy Rose was "driven by" Valadez, not that he owned it.
UPDATE public.intl_questions SET rationale = replace(rationale, 'Jesse Valadez owned the lowrider car', 'Jesse Valadez drove the lowrider car') WHERE question_id = 'EXT1262' AND position('Jesse Valadez owned the lowrider car' in rationale) > 0;
-- EXT1281: Explanation misspells the site as "Mistake Point"; the passage and other mentions say "Mistaken Point".
UPDATE public.intl_questions SET rationale = replace(rationale, 'formation at Mistake Point', 'formation at Mistaken Point') WHERE question_id = 'EXT1281' AND position('formation at Mistake Point' in rationale) > 0;
-- EXT2721: Choice A explanation says the 6B theropod had a longer stride "not shorter", but choice A itself says a longer stride, so this sentence wrongly implie
UPDATE public.intl_questions SET rationale = replace(rationale, 'Moreover, the therapod that left the La Torre 6B tracks had a longer average stride, not shorter: 5.57 meters, compared with 5.23 meters for the other set of tracks. ', '') WHERE question_id = 'EXT2721' AND position('Moreover, the therapod that left the La Torre 6B tracks had a longer average stride, not shorter: 5.57 meters, compared with 5.23 meters for the other set of tracks. ' in rationale) > 0;
-- EXT2752: Explanation says the Pilgrimage of Grace revolt came two years after the Dissolution, but the passage says the policy was introduced in 1536 and the c
UPDATE public.intl_questions SET rationale = replace(rationale, 'two years after it happened', 'in the same year it began') WHERE question_id = 'EXT2752' AND position('two years after it happened' in rationale) > 0;
-- EXT2758: Explanation attributes the easier-peeling benefit to Armijo's hypothesis, but the hypothesis is only about reducing roasting time; the peeling benefit
UPDATE public.intl_questions SET rationale = replace(rationale, 'Though Armijo''s hypothesis mentions a benefit of solar-roasting green chiles (easier peeling)', 'Though this finding mentions a benefit of solar-roasting green chiles (easier peeling)') WHERE question_id = 'EXT2758' AND position('Though Armijo''s hypothesis mentions a benefit of solar-roasting green chiles (easier peeling)' in rationale) > 0;
-- EXT2828: Explanation says Caddo is closely related to Totozoquean; passage says only that Caddo corn vocabulary resembles Totozoquean vocabulary (via contact t
UPDATE public.intl_questions SET rationale = replace(rationale, 'which is described as closely related to the Totozoquean language family', 'whose corn vocabulary is described as resembling that of the Totozoquean language family') WHERE question_id = 'EXT2828' AND position('which is described as closely related to the Totozoquean language family' in rationale) > 0;
-- EXT1320: Choice B explanation says Theia is mentioned in Text 2; Theia is named only in Text 1.
UPDATE public.intl_questions SET rationale = replace(rationale, 'Theia is mentioned in Text 2', 'Theia is mentioned in Text 1') WHERE question_id = 'EXT1320' AND position('Theia is mentioned in Text 2' in rationale) > 0;
-- EXT1343: Explanation says the consensus is that symbols signify "symbols or full words"; Text 2 says syllables or words.
UPDATE public.intl_questions SET rationale = replace(rationale, 'can signify either symbols or full words', 'can signify either syllables or full words') WHERE question_id = 'EXT1343' AND position('can signify either symbols or full words' in rationale) > 0;
-- EXT2146: Choice C explanation calls the comet "long-term"; passage says long-period. Also the quoted phrase from Text 2 is altered.
UPDATE public.intl_questions SET rationale = replace(rationale, 'a long-term comet', 'a long-period comet') WHERE question_id = 'EXT2146' AND position('a long-term comet' in rationale) > 0;
UPDATE public.intl_questions SET rationale = replace(rationale, 'geological layers that were deposited worldwide after the impact', 'geological layers deposited worldwide following the impact') WHERE question_id = 'EXT2146' AND position('geological layers that were deposited worldwide after the impact' in rationale) > 0;
-- EXT1411: Explanation says "the memoir tells" but the passage describes a book (Bengali Harlem) that draws on memoirs as one source, not a memoir.
UPDATE public.intl_questions SET rationale = replace(rationale, 'the memoir tells', 'the book tells') WHERE question_id = 'EXT1411' AND position('the memoir tells' in rationale) > 0;
-- EXT2311: Explanation says the cupid is near a "statue"; the passage describes artworks (paintings/depictions), not a statue.
UPDATE public.intl_questions SET rationale = replace(rationale, 'near a statue of a female figure who is fishing', 'near a female figure who is fishing in artworks') WHERE question_id = 'EXT2311' AND position('near a statue of a female figure who is fishing' in rationale) > 0;
-- EXT1876: Choice D explanation has a garbled sentence ("that until US traffic signals have contained lights ... only since") that contradicts the passage logic;
UPDATE public.intl_questions SET rationale = replace(rationale, 'rather, it addresses the idea that until US traffic signals have contained', 'rather, it addresses the idea that US traffic signals have contained') WHERE question_id = 'EXT1876' AND position('rather, it addresses the idea that until US traffic signals have contained' in rationale) > 0;
-- EXT2659: Explanation calls the physicist Joseph Webster throughout; passage says Joseph Weber.
UPDATE public.intl_questions SET rationale = replace(rationale, 'Joseph Webster''s research', 'Joseph Weber''s research') WHERE question_id = 'EXT2659' AND position('Joseph Webster''s research' in rationale) > 0;
UPDATE public.intl_questions SET rationale = replace(rationale, 'Webster''s experiments', 'Weber''s experiments') WHERE question_id = 'EXT2659' AND position('Webster''s experiments' in rationale) > 0;
UPDATE public.intl_questions SET rationale = replace(rationale, 'Webster''s work was foundational', 'Weber''s work was foundational') WHERE question_id = 'EXT2659' AND position('Webster''s work was foundational' in rationale) > 0;
UPDATE public.intl_questions SET rationale = replace(rationale, 'Webster''s work was supplementary', 'Weber''s work was supplementary') WHERE question_id = 'EXT2659' AND position('Webster''s work was supplementary' in rationale) > 0;
UPDATE public.intl_questions SET rationale = replace(rationale, 'Webster''s work was repetitive', 'Weber''s work was repetitive') WHERE question_id = 'EXT2659' AND position('Webster''s work was repetitive' in rationale) > 0;
UPDATE public.intl_questions SET rationale = replace(rationale, 'Webster''s work formed', 'Weber''s work formed') WHERE question_id = 'EXT2659' AND position('Webster''s work formed' in rationale) > 0;
UPDATE public.intl_questions SET rationale = replace(rationale, 'Webster''s work was ineffective', 'Weber''s work was ineffective') WHERE question_id = 'EXT2659' AND position('Webster''s work was ineffective' in rationale) > 0;
UPDATE public.intl_questions SET rationale = replace(rationale, 'Webster''s work was productive', 'Weber''s work was productive') WHERE question_id = 'EXT2659' AND position('Webster''s work was productive' in rationale) > 0;
-- EXT1332: the passage spells the researcher Trever
UPDATE public.intl_questions SET rationale = replace(rationale, 'Trevor thinks', 'Trever thinks') WHERE question_id = 'EXT1332' AND position('Trevor thinks' in rationale) > 0;
-- EXT1532: the passage says "prevalence of gestures"
UPDATE public.intl_questions SET rationale = replace(rationale, 'in which gestures are "prevalent,"', 'in which there is a "prevalence" of gestures,') WHERE question_id = 'EXT1532' AND position('in which gestures are "prevalent,"' in rationale) > 0;
-- EXT2091: the passage only poses a hypothetical
UPDATE public.intl_questions SET rationale = replace(rationale, 'The text then highlights an instance in which Western scrub-jays were studied in both settings but with conflicting results, indicating', 'The text then gives a hypothetical example in which studies of Western scrub-jays in both settings might produce conflicting results, indicating') WHERE question_id = 'EXT2091' AND position('The text then highlights an instance in which Western scrub-jays were studied in both settings but with conflicting results, indicating' in rationale) > 0;
-- EXT2785: the graph shows the highest spray-coated ETL at about 17%
UPDATE public.intl_questions SET rationale = replace(rationale, 'instead of a value between 12% and 14%', 'instead of a value between 16% and 18%') WHERE question_id = 'EXT2785' AND position('instead of a value between 12% and 14%' in rationale) > 0;